<template>
  <section>
    <div class="spread view-heading"><div><h2>Office performance overview</h2><div class="small muted">As of {{ fmtLong(today) }} · {{ state.entries.length }} tracked work items</div></div><div class="flexrow"><button class="btn" @click="openCalendar">Open today's calendar</button><button v-if="canEdit" class="btn primary" @click="emit('open-task-modal')">+ New entry</button></div></div>
    <div class="kpis"><div v-for="k in kpis" :key="k.label" :class="['kpi',k.cls]"><div class="lab">{{ k.label }}</div><div class="val">{{ k.value }}</div><div class="small muted">{{ k.note }}</div></div></div>
    <div class="grid g2" style="margin-top:14px">
      <div class="card"><div class="cardHead"><div><h3>Accomplishment trend</h3><div class="sub">Last 8 months — green = accomplished, blue = unfinished (target date)</div></div></div><div class="dashboard-bars"><div v-for="m in trend" :key="m.key" class="dashboard-bar-group"><div class="dashboard-bar-pair"><div class="dashboard-bar done" :style="{height:m.done/maxTrend*100+'%'}" :title="m.label + ': '+m.done+' accomplished'"><span>{{ m.done }}</span></div><div class="dashboard-bar open" :style="{height:m.open/maxTrend*100+'%'}" :title="m.label + ': '+m.open+' unfinished'"><span>{{ m.open }}</span></div></div><div class="small muted">{{ m.label }}</div></div></div><div class="calendar-legend legend"><span><i style="background:var(--done)"></i>Accomplished</span><span><i style="background:var(--open)"></i>Ongoing / pending</span></div></div>
      <div class="card"><div class="cardHead"><h3>Status mix</h3></div><div class="donutWrap"><svg viewBox="0 0 160 160" class="donut" role="img" :aria-label="stats.rate+'% completion rate'"><circle cx="80" cy="80" r="58" fill="none" stroke="var(--line)" stroke-width="20"/><circle v-for="s in statusArcs" :key="s.key" cx="80" cy="80" r="58" fill="none" :stroke="s.color" stroke-width="20" :stroke-dasharray="s.length+' '+(circumference-s.length)" :stroke-dashoffset="-s.offset" transform="rotate(-90 80 80)"/><text x="80" y="80" text-anchor="middle" class="donutN">{{ stats.rate }}%</text><text x="80" y="99" text-anchor="middle" class="ax" fill="var(--muted)" font-size="11">accomplished</text></svg><div class="legend"><span v-for="(s,key) in STATUS" :key="key" class="lgd"><i :style="{background:s.color}"></i>{{ s.short }} — <b>{{ stats[key] }}</b></span></div></div></div>
      <div class="card"><div class="cardHead"><div><h3>Needs attention</h3><div class="sub">Overdue and due within 7 days</div></div><button class="btn sm" @click="openTasks('overdue')">View all overdue</button></div><div v-if="!attention.length" class="empty">No overdue work or deadlines in the next 7 days.</div><div v-for="e in attention" :key="e.id" :class="['evItem',isOverdue(e)?'l':STATUS[e.status].ev]"><div class="t">{{ e.title }}</div><div class="meta"><span :class="['chip',isOverdue(e)?'late':e.status]">{{ isOverdue(e)?'Overdue':STATUS[e.status].short }}</span><span>{{ fmtMed(e.dueDate) }} · {{ relDay(e.dueDate) }}</span><span>{{ e.location }}</span></div><div v-if="canEdit" class="acts"><button class="btn sm" @click="updateEntry(e.id,{status:'done',completedDate:today})">Mark accomplished</button><button class="btn sm" @click="emit('edit-task',e)">Edit</button></div></div></div>
      <div class="card"><div class="cardHead"><h3>Work by category</h3></div><div v-if="!categories.length" class="empty">No records yet.</div><div v-for="g in categories" :key="g.name" class="hbar"><span class="nm">{{ g.name }}</span><span class="track"><i :style="{width:g.stats.total/maxCategory*100+'%'}"></i></span><span class="n">{{ g.stats.total }}</span></div></div>
      <div class="card"><div class="cardHead"><div><h3>Today at a glance</h3><div class="sub">Work and official travel today</div></div><div class="flexrow"><button class="btn sm" @click="openCalendar">Open calendar</button><button class="btn sm" @click="state.activeTab='weekly'">Weekly schedule</button></div></div><div class="dpStats"><span class="chip done">{{ todayInfo.done.length }} accomplished</span><span class="chip pend">{{ todayInfo.unfinished.length }} unfinished</span><span class="chip open">{{ todayInfo.spanning.length }} ongoing across today</span></div><div v-for="e in [...todayInfo.done,...todayInfo.unfinished,...todayInfo.spanning].slice(0,6)" :key="e.id" class="evItem"><b>{{ e.title }}</b><div class="meta">{{ STATUS[e.status].short }} · {{ e.location }}</div></div><div v-for="t in travelsOn(state.travels,today)" :key="t.id" class="evItem t"><b>{{ t.travellerName }}</b> <span class="chip t">T</span><div class="meta">{{ t.destination }}</div></div><div v-if="!todayInfo.done.length && !todayInfo.unfinished.length && !todayInfo.spanning.length && !travelsOn(state.travels,today).length" class="empty">No work or travel logged for today.</div></div>
      <div class="card"><div class="cardHead"><h3>Recent accomplishments</h3></div><div v-if="!recent.length" class="empty">No accomplishments logged yet.</div><div v-for="e in recent" :key="e.id" class="evItem d"><div class="t">{{ e.title }}</div><div class="meta">{{ fmtMed(plotDate(e)) }} · {{ e.category }} · {{ e.completedByName || e.createdByName }}</div><div v-if="e.remarks" class="rm">{{ e.remarks }}</div></div></div>
      <div class="card"><div class="cardHead"><div><h3>Personnel on travel <span class="chip t">T</span></h3><div class="sub">Today and the next 30 days · destination for each traveller</div></div><button class="btn sm" @click="state.activeTab='travel'">Travel Order</button></div><div v-if="!upcomingTravels.length" class="empty">No travel in the next 30 days.</div><div v-for="t in upcomingTravels" :key="t.id" class="evItem t"><div class="t">{{ t.travellerName }} <span v-if="t.from <= today" class="chip t on">on travel today</span></div><div class="meta"><b>{{ t.destination }}</b><span>{{ fmtRange(t.from,t.to) }}</span><span>{{ t.from <= today ? 'Returns '+relDay(t.to) : 'Departs '+relDay(t.from) }}</span></div><div class="rm">{{ t.purpose }}</div><div v-if="canEdit" class="acts"><button class="btn sm" @click="editingTravel={...t};showTravel=true">Edit</button><button class="btn sm danger" @click="removeTravel(t)">Delete</button></div></div><button v-if="canEdit" class="btn sm" @click="editingTravel=null;showTravel=true">+ Record a travel</button></div>
      <div class="card"><div class="cardHead"><h3>Travel this month</h3><div class="sub">{{ MONTHS[fromISO(today).getMonth()] }} {{ fromISO(today).getFullYear() }}</div></div><div v-if="!monthTravels.length" class="empty">No travel recorded this month.</div><div v-for="t in monthTravels" :key="t.id" class="evItem t"><b>{{ t.travellerName }}</b><div class="meta">{{ t.destination }} · {{ fmtRange(t.from,t.to) }} · {{ travelDays(t) }} days</div></div></div>
      <div class="card"><div class="cardHead"><div><h3>Team activity</h3><div class="sub">Work encoded per staff member</div></div><button class="btn sm" @click="openTasks('mine')">My records only</button></div><div class="tableWrap"><table class="tbl"><thead><tr><th>Personnel</th><th>Total</th><th>Accomplished</th><th>Unfinished</th></tr></thead><tbody><tr v-for="g in team" :key="g.name"><td>{{ g.name }}</td><td>{{ g.stats.total }}</td><td>{{ g.stats.done }}</td><td>{{ g.stats.open+g.stats.pend }}</td></tr></tbody></table></div></div>
      <div class="card"><div class="cardHead"><div><h3>My summary — {{ state.auth.name }}</h3><div class="sub">Based on the account signed in on this computer</div></div></div><div class="grid g2"><div v-for="k in myKpis" :key="k.label" :class="['kpi',k.cls]"><div class="lab">{{ k.label }}</div><div class="val">{{ k.value }}</div></div></div></div>
    </div>
    <TravelModal v-model="showTravel" :editing-item="editingTravel" />
  </section>
</template>
<script setup>
import {computed,ref} from 'vue';
import {state,saveUi,updateEntry,deleteTravel} from '../../store/state';
import {canDo} from '../../utils/auth';
import {todayISO,fromISO,toISO,addDays,fmtLong,fmtMed,fmtRange,relDay,mKey} from '../../utils/dateUtils';
import {summarize,plotDate,isOverdue,isOpen,entriesForDate,travelsOn,overlapsRange,travelDays} from '../../utils/trackerMetrics';
import {MONTHS,MONTHS_S,STATUS} from '../../utils/constants';
import TravelModal from '../travel/TravelModal.vue';
const emit=defineEmits(['open-task-modal','edit-task']);
const today=todayISO(),canEdit=computed(()=>canDo(state.auth.role,'edit'));
const stats=computed(()=>summarize(state.entries));
const showTravel=ref(false),editingTravel=ref(null);
const kpis=computed(()=>[{label:'Total entries',value:stats.value.total,note:stats.value.done+' accomplished · '+(stats.value.open+stats.value.pend)+' open'},{label:'Accomplished',value:stats.value.done,note:stats.value.rate+'% completion rate',cls:'done'},{label:'Ongoing',value:stats.value.open,note:stats.value.dueSoon+' due within 7 days',cls:'open'},{label:'Pending',value:stats.value.pend,note:'Not yet started',cls:'pend'},{label:'Overdue',value:stats.value.overdue,note:'Past target dates',cls:'late'},{label:'Beneficiaries served',value:stats.value.ben,note:'Across tracked activities'},{label:'This month',value:state.entries.filter(e=>mKey(plotDate(e))===mKey(today)).length,note:'Dated this month'}]);
const trend=computed(()=>{const now=fromISO(today);return Array.from({length:8},(_,i)=>{const d=new Date(now.getFullYear(),now.getMonth()-7+i,1),key=mKey(toISO(d));const s=summarize(state.entries.filter(e=>mKey(plotDate(e))===key));return {key,label:MONTHS_S[d.getMonth()],done:s.done,open:s.open+s.pend};});});
const maxTrend=computed(()=>Math.max(1,...trend.value.flatMap(m=>[m.done,m.open])));
const circumference=2*Math.PI*58;
const statusArcs=computed(()=>{let offset=0;return Object.entries(STATUS).map(([key,s])=>{const length=stats.value.total ? stats.value[key]/stats.value.total*circumference : 0;const arc={key,color:s.color,length,offset};offset+=length;return arc;});});
const attention=computed(()=>state.entries.filter(e=>isOverdue(e)||isOpen(e)&&e.dueDate>=today&&e.dueDate<=addDays(today,7)).sort((a,b)=>a.dueDate.localeCompare(b.dueDate)).slice(0,8));
function groups(key){const map=new Map();for(const e of state.entries){const name=key(e)||'Not recorded';if(!map.has(name))map.set(name,[]);map.get(name).push(e);}return [...map].map(([name,list])=>({name,stats:summarize(list)})).sort((a,b)=>b.stats.total-a.stats.total);}
const categories=computed(()=>groups(e=>e.category)),maxCategory=computed(()=>Math.max(1,...categories.value.map(g=>g.stats.total)));
const team=computed(()=>groups(e=>e.createdByName));
const todayInfo=computed(()=>entriesForDate(state.entries,today));
const recent=computed(()=>state.entries.filter(e=>e.status==='done').sort((a,b)=>plotDate(b).localeCompare(plotDate(a))).slice(0,5));
const upcomingTravels=computed(()=>state.travels.filter(t=>overlapsRange(t,today,addDays(today,30))).sort((a,b)=>a.from.localeCompare(b.from)));
const monthTravels=computed(()=>{const d=fromISO(today);return state.travels.filter(t=>overlapsRange(t,toISO(new Date(d.getFullYear(),d.getMonth(),1)),toISO(new Date(d.getFullYear(),d.getMonth()+1,0))));});
const mine=computed(()=>state.entries.filter(e=>e.createdBy===state.auth.id||e.completedBy===state.auth.id));
const myKpis=computed(()=>[{label:'My entries',value:mine.value.length},{label:'Accomplished by me',value:state.entries.filter(e=>e.completedBy===state.auth.id&&e.status==='done').length,cls:'done'},{label:'My work this month',value:mine.value.filter(e=>mKey(plotDate(e))===mKey(today)).length},{label:'My overdue',value:summarize(mine.value).overdue,cls:'late'}]);
function openCalendar(){const d=fromISO(today);state.selDate=today;state.calYear=d.getFullYear();state.calMonth=d.getMonth();state.calView='month';state.activeTab='calendar';saveUi();}
function openTasks(quick){Object.assign(state.filters,{q:'',status:'',category:'',location:'',user:'',from:'',to:'',quick});state.activeTab='tasks';saveUi();}
function removeTravel(t){if(confirm(`Delete travel to ${t.destination}?`))deleteTravel(t.id);}
</script>
